<?php declare(strict_types=1); $programmes=$dashboard['programmes']??[]; $applications=$dashboard['applications']??[]; $applied=array_column($applications,'programme_public_id'); ?>
<section class="section"><div class="container-narrow"><div class="section-heading"><p class="eyebrow">Professional development</p><h1>Programme applications</h1><p>Save a draft or submit an application for a published professional programme. Submission does not guarantee approval or enrolment.</p></div>
<?php if($message):?><div class="notice" role="status"><?= $e($message) ?></div><?php endif;?><?php if($error):?><div class="form-error" role="alert"><?= $e($error) ?></div><?php endif;?>
<?php if($programmes!==[]):?><details class="admin-panel"><summary>Start a programme application</summary><form method="post" action="/account/programme-applications/draft" class="form-grid"><?= $csrf->field() ?><label>Programme<select name="programme" required><option value="">Select a published programme</option><?php foreach($programmes as $programme):?><option value="<?= $e($programme['public_id']) ?>" <?= in_array($programme['public_id'],$applied,true)?'disabled':'' ?>><?= $e($programme['code'].' — '.$programme['name'].(in_array($programme['public_id'],$applied,true)?' (already applied)':'')) ?></option><?php endforeach;?></select></label><label>Highest qualification<input name="highest_qualification" maxlength="160"></label><label>Current organisation<input name="current_organisation" maxlength="200"></label><label class="field-wide">Professional background<textarea name="professional_background" rows="5" maxlength="5000"></textarea></label><label class="field-wide">Why do you want to join this programme?<textarea name="motivation" rows="5" maxlength="5000"></textarea></label><button class="btn btn-navy" type="submit">Save draft</button></form></details><?php else:?><div class="empty-state"><p>No programmes are currently published for application.</p></div><?php endif;?>
<div class="admin-list"><h2>Your applications</h2><?php if($applications===[]):?><p>You have not started a programme application.</p><?php endif;?><?php foreach($applications as $application):?><article class="admin-panel"><div class="programme-card-top"><strong><?= $e($application['programme_code'].' — '.$application['programme_name']) ?></strong><span class="status-pill"><?= $e(ucwords(str_replace('_',' ',$application['status']))) ?></span></div><?php if($application['application_reference']):?><p>Reference: <strong><?= $e($application['application_reference']) ?></strong></p><?php endif;?><?php if($application['enrolment_number']):?><p>Enrolment number: <strong><?= $e($application['enrolment_number']) ?></strong></p><?php endif;?><?php if($application['decision_note']):?><p><?= $e($application['decision_note']) ?></p><?php endif;?>
<?php if($application['status']==='draft'):?><form method="post" action="/account/programme-applications/draft" class="form-grid"><?= $csrf->field() ?><input type="hidden" name="application_public_id" value="<?= $e($application['public_id']) ?>"><input type="hidden" name="programme" value="<?= $e($application['programme_public_id']) ?>"><label>Highest qualification<input name="highest_qualification" maxlength="160" value="<?= $e($application['highest_qualification']??'') ?>"></label><label>Current organisation<input name="current_organisation" maxlength="200" value="<?= $e($application['current_organisation']??'') ?>"></label><label class="field-wide">Professional background<textarea name="professional_background" rows="5" maxlength="5000"><?= $e($application['professional_background']??'') ?></textarea></label><label class="field-wide">Motivation<textarea name="motivation" rows="5" maxlength="5000"><?= $e($application['motivation']??'') ?></textarea></label><button class="btn btn-outline-navy" type="submit">Update draft</button></form><form method="post" action="/account/programme-applications/submit" class="form-grid"><?= $csrf->field() ?><input type="hidden" name="application_public_id" value="<?= $e($application['public_id']) ?>"><label>Declaration name<input name="declaration_name" maxlength="200" required></label><label><input type="checkbox" name="declaration_accepted" value="1" required> I confirm that the information supplied is accurate.</label><button class="btn btn-navy" type="submit">Submit application</button></form><?php endif;?>
<?php if(in_array($application['status'],['draft','submitted','review'],true)):?><form method="post" action="/account/programme-applications/<?= rawurlencode($application['public_id']) ?>/withdraw"><?= $csrf->field() ?><button class="btn btn-outline" type="submit">Withdraw application</button></form><?php endif;?></article><?php endforeach;?></div>
</div></section>
